package com.google.gson.stream;

import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.fail;

public class JsonWriter_value_TriageGen0Test {

    private StringWriter stringWriter;
    private JsonWriter jsonWriter;

    @Before
    public void setUp() throws IOException {
        stringWriter = new StringWriter();
        jsonWriter = new JsonWriter(stringWriter);
    }

    @Test
    public void testValuePositiveLong() throws IOException {
        jsonWriter.beginObject()
                 .name("value")
                 .value(123456789L)
                 .endObject();
        assertEquals("{\"value\":123456789}", stringWriter.toString());
    }

    @Test
    public void testValueNegativeLong() throws IOException {
        jsonWriter.beginObject()
                 .name("value")
                 .value(-987654321L)
                 .endObject();
        assertEquals("{\"value\":-987654321}", stringWriter.toString());
    }

    @Test
    public void testValueZeroLong() throws IOException {
        jsonWriter.beginObject()
                 .name("value")
                 .value(0L)
                 .endObject();
        assertEquals("{\"value\":0}", stringWriter.toString());
    }

    @Test
    public void testValueMaxLong() throws IOException {
        jsonWriter.beginObject()
                 .name("value")
                 .value(Long.MAX_VALUE)
                 .endObject();
        assertEquals("{\"value\":9223372036854775807}", stringWriter.toString());
    }

    @Test
    public void testValueMinLong() throws IOException {
        jsonWriter.beginObject()
                 .name("value")
                 .value(Long.MIN_VALUE)
                 .endObject();
        assertEquals("{\"value\":-9223372036854775808}", stringWriter.toString());
    }

    @Test(expected = IOException.class)
    public void testValueWithIOException() throws IOException {
        jsonWriter.beginObject()
                 .name("value")
                 .value(123456789L);
        // Simulating IOException
        throw new IOException("Simulated IOException");
    }

    @Test
    public void testValueChainedCalls() throws IOException {
        jsonWriter.beginObject()
                 .name("value1")
                 .value(123L)
                 .name("value2")
                 .value(456L)
                 .endObject();
        assertEquals("{\"value1\":123,\"value2\":456}", stringWriter.toString());
    }

    @Test
    public void testValueEmptyObject() throws IOException {
        jsonWriter.beginObject().endObject();
        assertEquals("{}", stringWriter.toString());
    }
}
